using System;

namespace Tsumo.Cli
{
    public static class Node_modules_Tsumo_engine_src_utils_int32
    {
        public static Func<double, int?> toInt32
        {
            get;
            private set;
        } = default(Func<double, int?>)!;
        public static Func<string, int?> parseInt32
        {
            get;
            private set;
        } = default(Func<string, int?>)!;
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            toInt32 = (double value) =>
            {
                if (Tsonic.CSharp.Js.Number.isInteger(value) && value >= -2147483648 && value <= 2147483647)
                {
                    return (int)value;
                }
                return null;
            };
            parseInt32 = (string value) =>
            {
                string trimmed = Tsonic.CSharp.Js.String.trim(value);
                if (!new Tsonic.CSharp.Js.RegExp("^-?\\d+$", "").test(trimmed))
                {
                    return null;
                }
                return toInt32(Tsonic.CSharp.Js.Number.parseInt(trimmed, 10));
            };
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
}
